 "content": "def transform(grid):
    """Replicate the marked shape into every translate whose cells are all zero."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            if value != 0:
                counts[value] = counts.get(value, 0) + 1
    if not counts:
        return [row[:] for row in grid]
    background = max(counts, key=counts.get)
    colors = [(count, value) for value, count in counts.items() if value != background]
    if not colors:
        return [row[:] for row in grid]
    marker = min(colors)[1]
    cells = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == marker]
    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    shape = [(r-r0, c-c0) for r, c in cells]
    sh = max(r for r, c in shape) + 1
    sw = max(c for r, c in shape) + 1
    out = [row[:] for row in grid]
    for top in range(h-sh+1):
        for left in range(w-sw+1):
            if all(grid[top+dr][left+dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[top+dr][left+dc] = marker
    return out
